using System.Security.Principal;
using System.Threading;

public class AuthorizationHelper
{
    // Thread.CurrentPrincipal was set by WCF / ASP.NET Framework
    // per-request. In .NET 10 async code, await continuations run on
    // different threads — CurrentPrincipal is NOT propagated across
    // await points in ASP.NET Core.
    public static bool IsInRole(string role)
    {
        return Thread.CurrentPrincipal?.IsInRole(role) ?? false;
    }

    public static string GetCurrentUser()
    {
        return Thread.CurrentPrincipal?.Identity?.Name ?? "anonymous";
    }

    // Also common: setting Thread.CurrentPrincipal in a custom
    // HTTP module or message handler, then reading it elsewhere.
    public static void SetPrincipal(IPrincipal principal)
    {
        Thread.CurrentPrincipal = principal;
    }

    // WCF variant: using ServiceSecurityContext
    // public static string GetWcfCaller()
    // {
    //     return ServiceSecurityContext.Current?.PrimaryIdentity?.Name;
    // }
}
